// One HTML-entity decode pass for brand-name HTML/SVG text. Named refs come from the
// WHATWG HTML named character references table. XML/SVG require `;`. HTML mode also
// decodes the optional-semicolon names (`&nbsp` without `;`). Unknown names stay as
// source text. Numeric refs outside Unicode become U+FFFD.
// Regenerated by: tsx scripts/generate-html-named-entities.ts --from <entities.json>
import html5NamedEntities from './html5-named-entities.json' with { type: 'json' }
import html5OptionalNamedEntities from './html5-named-entities-optional.json' with { type: 'json' }

export const HTML5_NAMED_ENTITY_SOURCE = 'https://html.spec.whatwg.org/entities.json'

export type NamedReferenceMode = 'xml' | 'html'

type ConsumedReference = { chars: string; consumed: number }

const NAMED = new Map<string, string>(Object.entries(html5NamedEntities as Record<string, string>))
const OPTIONAL = new Map<string, string>(
  Object.entries(html5OptionalNamedEntities as Record<string, string>)
)

export const HTML5_NAMED_ENTITY_COUNT = NAMED.size
export const HTML5_OPTIONAL_SEMICOLON_NAMED_ENTITY_COUNT = OPTIONAL.size

function isNameStart(code: number): boolean {
  return (code >= 65 && code <= 90) || (code >= 97 && code <= 122)
}

function isNameChar(code: number): boolean {
  return isNameStart(code) || (code >= 48 && code <= 57)
}

function isDigit(code: number): boolean {
  return code >= 48 && code <= 57
}

function isHex(code: number): boolean {
  return isDigit(code) || (code >= 65 && code <= 70) || (code >= 97 && code <= 102)
}

function decodeCodePoint(value: number): string {
  const invalid =
    !Number.isFinite(value) ||
    value <= 0 ||
    value > 0x10ffff ||
    (value >= 0xd800 && value <= 0xdfff)
  return invalid ? '\uFFFD' : String.fromCodePoint(value)
}

function scanWhile(rest: string, start: number, pred: (code: number) => boolean): number {
  let end = start
  while (end < rest.length && pred(rest.charCodeAt(end))) end += 1
  return end
}

function longestOptionalMatch(name: string): ConsumedReference | undefined {
  for (let length = name.length; length >= 1; length -= 1) {
    const chars = OPTIONAL.get(name.slice(0, length))
    if (chars !== undefined) return { chars, consumed: length }
  }
  return undefined
}

function consumeTerminatedNumber(
  rest: string,
  digitsStart: number,
  pred: (code: number) => boolean,
  radix: number
): ConsumedReference | undefined {
  const end = scanWhile(rest, digitsStart, pred)
  if (end === digitsStart || rest.charCodeAt(end) !== 59) return undefined
  return {
    chars: decodeCodePoint(Number.parseInt(rest.slice(digitsStart, end), radix)),
    consumed: end + 1,
  }
}

function consumeNumeric(rest: string): ConsumedReference | undefined {
  if (rest.charCodeAt(0) !== 35) return undefined
  if (rest.charCodeAt(1) === 120 || rest.charCodeAt(1) === 88) {
    return consumeTerminatedNumber(rest, 2, isHex, 16)
  }
  return consumeTerminatedNumber(rest, 1, isDigit, 10)
}

function consumeNamed(rest: string, mode: NamedReferenceMode): ConsumedReference | undefined {
  if (!isNameStart(rest.charCodeAt(0))) return undefined
  const end = scanWhile(rest, 1, isNameChar)
  const name = rest.slice(0, end)
  if (rest.charCodeAt(end) === 59) {
    const chars = NAMED.get(name)
    return chars === undefined ? undefined : { chars, consumed: end + 1 }
  }
  return mode === 'html' ? longestOptionalMatch(name) : undefined
}

function consumeReference(rest: string, mode: NamedReferenceMode): ConsumedReference | undefined {
  return consumeNumeric(rest) ?? consumeNamed(rest, mode)
}

export function decodeHtmlEntities(source: string, mode: NamedReferenceMode = 'xml'): string {
  let out = ''
  let index = 0
  while (index < source.length) {
    const amp = source.indexOf('&', index)
    if (amp === -1) {
      out += source.slice(index)
      break
    }
    out += source.slice(index, amp)
    const hit = consumeReference(source.slice(amp + 1), mode)
    if (hit === undefined) {
      out += '&'
      index = amp + 1
      continue
    }
    out += hit.chars
    index = amp + 1 + hit.consumed
  }
  return out
}
